; Sunspire Keep, the palace on the terrace from the inside. The throne room at the north: the King's
; throne on its dais under the sun, tall windows down the back wall pouring light across the marble,
; Aurelian banners between them, the royal carpet from the steps down between the pillars and the
; guards, and the court along the sides. Through the arch, the great hall on the way out: the war
; table at its west end, a desk and a little wine table at its east end, and the door back out onto
; the terrace. Lit, and no fog: it's the palace.

[map]
id = sunspire-keep
name = Sunspire Keep
tileset = keep
size = 44 34
dark = no
fog = no
music = Court

[legend]
, = marble
* = marble-gold
c = carpet
d = dais
^ = steps
# = wall-top
- = wall-high
| = wall-face
_ = wall-base
n = window-high
w = window

