[objects]
spawn start 21.5 10.5 facing=up
spawn door 21.5 31.5 facing=up
exit door 20 33 w=4 to=back

; The audience. It plays as soon as you're shown in with the Sunheart, which is why you arrive
; before the dais and not at the door.
scene a1-c4-03 21.5 10.5 talk=a1-c4-03 when=a1-c4-02 unless=a1-c4-03

; The dais: the throne under its sun with the King before it, the Princess at his right hand and the
; Lord Chancellor at his left, guards at its corners, braziers either side of the steps, and the two
; great banners behind it. Once court's over the Chancellor's off down to the great hall to wait for
; the Soul-Bound, and he's back at the King's left after.
prop sun-throne 21.5 6.6
prop sun-banner 17 3.5
prop sun-banner 26 3.5
prop brazier 16.5 8.2
prop brazier 26.5 8.2
prop sun-inlay 21.5 13.1
npc leon 21.5 6.75 cast=leon facing=down
npc elara 19 7 cast=elara facing=down
npc crane 24 7 cast=crane facing=down unless=a1-c4-03
npc crane-court 24 7 cast=crane facing=down when=a1-c4-04
npc guard-1 14.8 6.5 cast=royal-guard facing=down
npc guard-2 28.2 6.5 cast=royal-guard facing=down

; Where A1-C4-03 has them for the audience, which is where they stand: the King before the throne,
; the Princess at his right hand, the Lord Chancellor at his left. Every guard here is a royal-guard,
; so the audience's royal-guards are all of them.
spawn throne 21.5 6.75 facing=down
spawn throne-right 19 7 facing=down
spawn throne-left 24 7 facing=down

; The windows down the back wall, the sun lying across the floor from each, and the banners between.
prop light-shaft 4.0625 7.625
prop light-shaft 9.0625 7.625
prop light-shaft 14.0625 7.625
prop light-shaft 30.0625 7.625
prop light-shaft 35.0625 7.625
prop light-shaft 40.0625 7.625
prop sun-banner 6 3.5
prop sun-banner 11 3.5
prop sun-banner 32 3.5
prop sun-banner 37 3.5

; The nave and its aisles: a colonnade down either side, guards by the arch, a statue of the old
; war in each corner by the windows, flowers under the banners, and the court standing about the
; aisles, watching.
prop pillar-marble 9.5 9.6
prop pillar-marble 9.5 15.6
prop pillar-marble 33.5 9.6
prop pillar-marble 33.5 15.6
prop guard-statue 1.5 5.6
prop guard-statue 41.5 5.6
prop planter-pink 6 4.4
prop planter-pink 11 4.4
prop planter-pink 32 4.4
prop planter-pink 37 4.4
prop cypress-pot 1.5 16.2
prop cypress-pot 41.5 16.2
npc guard-3 18.4 15.8 cast=royal-guard facing=right
npc guard-4 24.6 15.8 cast=royal-guard facing=left
npc courtier-1 5 9.5 look=707 name="A Courtier" facing=right say="The King's in a good mood. Don't spoil it.|Velvet in this heat. I ask you.|The Chancellor's watching. He's always watching."
npc courtier-2 6.4 11 look=733 name="A Lady of the Court" facing=right say="Heroes, apparently. They look tired.|Is that blood on your boot? How thrilling.|The Princess rode in at dawn again. Unchaperoned."
npc courtier-3 37.6 9.8 look=751 name="A Courtier" facing=left say="Forty years of peace, and they want a war.|The Chancellor says it's nothing. The Chancellor's usually right.|Mind the carpet. It's older than your grandmother."
npc courtier-4 36.5 12.5 look=768 name="A Scribe of the Court" facing=left say="I write down what the King says. All of it.|Today's been a lot of writing.|Doomward, Greywatch, Hollowed. My quill's never been so busy."
npc courtier-5 13.5 12 look=786 name="A Courtier" facing=right say="Bow lower. No, lower. Oh, never mind.|I came for the gossip. There's so much of it today."

; The arch through to the great hall, and a statue either side of it on the hall side.
prop keep-arch 21.5 20.5
prop guard-statue 17 21.4
prop guard-statue 26 21.4

