npc guard-6 24.4 32 cast=royal-guard facing=up

; The war room end: the war table on its carpet with Fable on it, braziers either side, and a
; captain over it.
prop war-table 6 26.4
prop brazier 2.5 23.6
prop brazier 9.5 23.6
npc captain 6 25 look=789 name="A Captain of the Guard" facing=down say="Greywatch holds. Greywatch always holds.|Forty men a company, and half the companies on paper.|Don't touch the markers. Took me all morning."
npc officer 9.6 27.6 look=812 name="A Lieutenant" facing=left say="The Captain's been at that table since dawn.|Red markers are them. Blue are us. There are more red ones every week."

; The chancellor's end: a desk on its carpet, a chair behind it, the wine, and Crane waiting there
; for the Soul-Bound after court.
prop armchair 37 22.5
prop royal-desk 37 23.8
prop wine-table 34.5 27.4
prop potted-plant 41 26
prop book-crate 40.2 23.2
npc crane-hall 32.6 27.8 cast=crane facing=left when=a1-c4-03 unless=a1-c4-04
trigger hall-crane 1 28 w=42 h=2 talk=a1-c4-04 when=a1-c4-03 unless=a1-c4-04

; Where A1-C4-04 leaves you: on down the hall from the Soul-Bound and the Chancellor, looking back.
spawn gallery-end 11.5 29.5 facing=right

; What the two of you say: the windows as you go down the aisle, and the hall past the arch.
trigger bark-keep-windows 17 11 w=10 h=3 bark=keep-windows
trigger bark-keep-hall 14 22 w=16 h=2 bark=keep-hall
